export type TaskLedgerEventType =
  | 'submitted'
  | 'accepted'
  | 'rejected'
  | 'started'
  | 'completed'
  | 'failed'
  | 'cancelled'
  | (string & {});

export interface TaskLedgerEvent<TPayload = unknown> {
  id?: string;
  workspaceId: string;
  batchIdempotencyKey: string;
  type: TaskLedgerEventType;
  payload?: TPayload;
  occurredAt?: string;
  timestamp?: string;
  [key: string]: unknown;
}

export interface PendingTaskLedgerItem {
  id: string;
  batchIdempotencyKey: string;
  workspaceId: string;
  status: 'pending';
  type: TaskLedgerEventType;
  payload?: unknown;
  submittedAt?: string;
  event: TaskLedgerEvent;
}

export interface AcceptedTaskLedgerItem {
  id: string;
  batchIdempotencyKey: string;
  workspaceId: string;
  status: 'accepted';
  type: TaskLedgerEventType;
  payload?: unknown;
  submittedAt?: string;
  acceptedAt?: string;
  event: TaskLedgerEvent;
}

export interface TaskLedgerWorkingContextProjection {
  workspaceId: string;
  pending: PendingTaskLedgerItem[];
  accepted: AcceptedTaskLedgerItem[];
  events: TaskLedgerEvent[];
}

export interface WorkingContextTask {
  id: string;
  batchIdempotencyKey: string;
  workspaceId: string;
  status: 'pending' | 'accepted';
  type: TaskLedgerEventType;
  payload?: unknown;
  submittedAt?: string;
  acceptedAt?: string;
  event: TaskLedgerEvent;
}

export interface WorkingContextProjection {
  workspaceId: string;
  tasks: WorkingContextTask[];
  pending: PendingTaskLedgerItem[];
  accepted: AcceptedTaskLedgerItem[];
}

function eventTime(event: TaskLedgerEvent): string | undefined {
  const value = event.occurredAt ?? event.timestamp;
  return typeof value === 'string' ? value : undefined;
}

function eventId(event: TaskLedgerEvent, index: number): string {
  if (typeof event.id === 'string' && event.id.length > 0) return event.id;
  const key = event.batchIdempotencyKey;
  return key.length > 0 ? key : `${event.workspaceId}:${index}`;
}

function eventType(event: TaskLedgerEvent): TaskLedgerEventType {
  const candidate = event.type ?? (event.status as TaskLedgerEventType | undefined);
  return typeof candidate === 'string' && candidate.length > 0 ? candidate : 'submitted';
}

function eventPayload(event: TaskLedgerEvent): unknown {
  return event.payload;
}

function isTerminal(type: string): boolean {
  return ['rejected', 'completed', 'failed', 'cancelled', 'canceled'].includes(type.toLowerCase());
}

function isAccepted(type: string): boolean {
  return ['accepted', 'started', 'completed'].includes(type.toLowerCase());
}

/**
 * Projects the authoritative ledger event stream. The projection deliberately keeps
 * only the latest state for each idempotency key and never writes derived state.
 */
export function projectTaskLedgerWorkingContext(
  workspaceId: string,
  events: readonly TaskLedgerEvent[],
): TaskLedgerWorkingContextProjection {
  const scoped = events.filter((event) => event.workspaceId === workspaceId);
  const latest = new Map<string, { event: TaskLedgerEvent; index: number }>();

  for (let index = 0; index < scoped.length; index += 1) {
    const event = scoped[index];
    latest.set(event.batchIdempotencyKey, { event, index });
  }

  const pending: PendingTaskLedgerItem[] = [];
  const accepted: AcceptedTaskLedgerItem[] = [];

  for (const { event, index } of latest.values()) {
    const type = eventType(event);
    const id = eventId(event, index);
    const submittedAt = eventTime(event);
    if (isTerminal(type)) continue;
    if (isAccepted(type)) {
      accepted.push({
        id,
        batchIdempotencyKey: event.batchIdempotencyKey,
        workspaceId,
        status: 'accepted',
        type,
        payload: eventPayload(event),
        submittedAt,
        acceptedAt: submittedAt,
        event,
      });
    } else {
      pending.push({
        id,
        batchIdempotencyKey: event.batchIdempotencyKey,
        workspaceId,
        status: 'pending',
        type,
        payload: eventPayload(event),
        submittedAt,
        event,
      });
    }
  }

  const order = (left: { id: string }, right: { id: string }): number =>
    left.id.localeCompare(right.id);
  pending.sort(order);
  accepted.sort(order);

  return { workspaceId, pending, accepted, events: [...scoped] };
}

export function toWorkingContextProjection(
  workspaceId: string,
  events: readonly TaskLedgerEvent[],
): WorkingContextProjection {
  const projection = projectTaskLedgerWorkingContext(workspaceId, events);
  return {
    workspaceId,
    tasks: [...projection.pending, ...projection.accepted],
    pending: projection.pending,
    accepted: projection.accepted,
  };
}

export function parseTaskLedgerJsonl(content: string, workspaceId?: string): TaskLedgerEvent[] {
  const events: TaskLedgerEvent[] = [];
  const lines = content.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const parsed: unknown = JSON.parse(trimmed);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('Invalid task ledger event');
    }
    const event = parsed as TaskLedgerEvent;
    if (typeof event.workspaceId !== 'string' || typeof event.batchIdempotencyKey !== 'string') {
      throw new Error('Invalid task ledger event');
    }
    if (workspaceId !== undefined && event.workspaceId !== workspaceId) continue;
    events.push(event);
  }
  return events;
}

export function serializeTaskLedgerEvent(event: TaskLedgerEvent): string {
  return `${JSON.stringify(event)}\n`;
}

export const projectWorkingContext = toWorkingContextProjection;
export const parseTaskLedger = parseTaskLedgerJsonl;

import { promises as fs } from 'node:fs';
import path from 'node:path';
import {
  parseTaskLedgerJsonl,
  projectTaskLedgerWorkingContext,
  serializeTaskLedgerEvent,
  toWorkingContextProjection,
  type TaskLedgerEvent,
  type TaskLedgerWorkingContextProjection,
  type WorkingContextProjection,
} from '../../shared/task-ledger-working-context';

export interface TaskLedgerWorkingContextOptions {
  workspaceId: string;
  workspaceRoot: string;
  ledgerDirectory?: string;
  ledgerFileName?: string;
}

export type AppendTaskLedgerEventInput = Omit<TaskLedgerEvent, 'workspaceId'> & {
  workspaceId?: string;
};

/**
 * Working Context adapter for the existing workspace Task Ledger.
 *
 * There is intentionally no independent persistence here: the JSONL ledger is
 * both the write-ahead event source and the source used to build projections.
 */
export class TaskLedgerWorkingContext {
  private readonly workspaceId: string;
  private readonly workspaceRoot: string;
  private readonly ledgerDirectory: string;
  private readonly ledgerFileName: string;

  constructor(options: TaskLedgerWorkingContextOptions) {
    this.workspaceId = options.workspaceId;
    this.workspaceRoot = options.workspaceRoot;
    this.ledgerDirectory = options.ledgerDirectory ?? path.join(options.workspaceRoot, '.task-ledger');
    this.ledgerFileName = options.ledgerFileName ?? 'ledger.jsonl';
  }

  get workspace(): string {
    return this.workspaceId;
  }

  get ledgerPath(): string {
    return path.join(this.ledgerDirectory, this.ledgerFileName);
  }

  private scopedLedgerPath(workspaceId = this.workspaceId): string {
    if (workspaceId === this.workspaceId) return this.ledgerPath;
    return path.join(this.ledgerDirectory, `${workspaceId}.${this.ledgerFileName}`);
  }

  async appendEvent(input: AppendTaskLedgerEventInput): Promise<TaskLedgerEvent> {
    const workspaceId = input.workspaceId ?? this.workspaceId;
    if (workspaceId !== this.workspaceId) {
      throw new Error(`Task ledger workspace mismatch: expected ${this.workspaceId}`);
    }
    if (!input.batchIdempotencyKey || typeof input.batchIdempotencyKey !== 'string') {
      throw new Error('batchIdempotencyKey is required');
    }

    const existing = await this.readEvents();
    const duplicate = existing.find(
      (event) => event.workspaceId === workspaceId && event.batchIdempotencyKey === input.batchIdempotencyKey,
    );
    if (duplicate) return duplicate;

    const event: TaskLedgerEvent = {
      ...input,
      workspaceId,
      occurredAt: input.occurredAt ?? input.timestamp ?? new Date().toISOString(),
    };

    await fs.mkdir(this.ledgerDirectory, { recursive: true });
    const handle = await fs.open(this.ledgerPath, 'a', 0o600);
    try {
      await handle.writeFile(serializeTaskLedgerEvent(event), 'utf8');
      await handle.sync();
    } finally {
      await handle.close();
    }
    return event;
  }

  async append(input: AppendTaskLedgerEventInput): Promise<TaskLedgerEvent> {
    return this.appendEvent(input);
  }

  async readEvents(workspaceId = this.workspaceId): Promise<TaskLedgerEvent[]> {
    let content: string;
    try {
      content = await fs.readFile(this.scopedLedgerPath(workspaceId), 'utf8');
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === 'ENOENT') return [];
      throw error;
    }
    return parseTaskLedgerJsonl(content, workspaceId);
  }

  async read(workspaceId = this.workspaceId): Promise<TaskLedgerEvent[]> {
    return this.readEvents(workspaceId);
  }

  async project(workspaceId = this.workspaceId): Promise<TaskLedgerWorkingContextProjection> {
    const events = await this.readEvents(workspaceId);
    return projectTaskLedgerWorkingContext(workspaceId, events);
  }

  async getWorkingContext(workspaceId = this.workspaceId): Promise<WorkingContextProjection> {
    const events = await this.readEvents(workspaceId);
    return toWorkingContextProjection(workspaceId, events);
  }
}

export function createTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextOptions,
): TaskLedgerWorkingContext {
  return new TaskLedgerWorkingContext(options);
}

export {
  parseTaskLedgerJsonl,
  projectTaskLedgerWorkingContext,
  toWorkingContextProjection,
} from '../../shared/task-ledger-working-context';

export type {
  TaskLedgerEvent,
  TaskLedgerWorkingContextProjection,
  WorkingContextProjection,
} from '../../shared/task-ledger-working-context';

